// PYNQ-Z2 board wrapper around the unchanged soc_top (fpga/README.md).
//
//   clk125 (board, 125 MHz) -> MMCM -> clk (1000 MHz VCO / CLK_DIV = 50 MHz)
//   reset: held while the MMCM is unlocked, BTN0 is pressed or the VIO soft
//          reset is 1, and for 16 clocks after all clear; synchronised to clk
//   VIO (vio_cfg, generated by build.tcl; driven by fpga/run.tcl over JTAG):
//     out: vio_ctrl, vio_seed, vio_a, vio_b -> soc_top cfg_in (firmware job
//          config, see fpga/fw/fpga_demo.c); vio_rst = soft reset (reruns the job)
//     in:  mon_result, mon_words (result words since reset), mon_runs (firmware
//          starts since configuration), mon_unlocks (MMCM lock losses)
//     Define CARCH_NO_VIO to replace it with its power-up values (build.tcl sim).
//   soc_top: PicoRV32 + 64 KB RAM (firmware preloaded) + accelerator
//            (ENABLE_ACCEL = 0: no accelerator, the CPU-only baseline)
//   uart_result_bridge: every result-port word -> "XXXXXXXX\r\n" on uart_tx
//   ILA taps: dbg_result / dbg_valid (see build.tcl, hw.tcl)
//   LEDs: 0 heartbeat, 1 PASS (last word was 1), 2 FAIL/trap/bus error,
//         3 bridge FIFO overflow
//
// Firmware: path of the $readmemh image, from fw_path.vh (written by
// build.tcl / sim.tcl) so the path is absolute on any machine.
`include "fw_path.vh"

module fpga_top #(
    parameter CLK_DIV = 20,             // 20 -> 50 MHz, 40 -> 25 MHz
    parameter BAUD = 2500000,           // exact at 50 and 25 MHz (20 / 10 clocks per bit)
    parameter [0:0] ENABLE_ACCEL = 1    // 0: CPU-only baseline (build.tcl baseline)
) (
    input  wire clk125,
    input  wire btn0,                   // active high
    output wire [3:0] led,
    output wire uart_tx
);
    localparam CLK_HZ = 1000000000 / CLK_DIV;

    // ---------------------------------------------------------------- clock
    wire clk_mmcm, clk_fb, locked, clk;

    MMCME2_BASE #(
        .CLKIN1_PERIOD(8.0),
        .DIVCLK_DIVIDE(1),
        .CLKFBOUT_MULT_F(8.0),          // 125 MHz x 8 = 1000 MHz VCO
        .CLKOUT0_DIVIDE_F(CLK_DIV)
    ) u_mmcm (
        .CLKIN1(clk125), .CLKFBIN(clk_fb), .CLKFBOUT(clk_fb),
        .CLKOUT0(clk_mmcm), .LOCKED(locked), .RST(1'b0), .PWRDWN(1'b0),
        .CLKFBOUTB(), .CLKOUT0B(), .CLKOUT1(), .CLKOUT1B(), .CLKOUT2(),
        .CLKOUT2B(), .CLKOUT3(), .CLKOUT3B(), .CLKOUT4(), .CLKOUT5(), .CLKOUT6()
    );
    BUFG u_bufg (.I(clk_mmcm), .O(clk));

    // ---------------------------------------------------------------- VIO
    // Power-up values (also the IP's INIT values in build.tcl): the original
    // 4x4x4 demo, matrices taken from vio_a / vio_b.
    localparam [31:0]  INIT_CTRL = 32'h0021_0204;   // M=4, K=4, N=4, matrix mode
    localparam [31:0]  INIT_SEED = 32'h0000_0001;
    localparam [127:0] INIT_A = 128'h03FE0100_0002FD05_020100FF_04030201;
    localparam [127:0] INIT_B = 128'h02FF0101_0100FE03_00010100_FF020001;

    wire [31:0] vio_ctrl, vio_seed;
    wire [127:0] vio_a, vio_b;
    wire vio_rst;
    wire [31:0] result;
    reg  [15:0] words = 16'd0, runs = 16'd0, unlocks = 16'd0;
    (* dont_touch = "true" *) wire [31:0] mon_result = result;
    (* dont_touch = "true" *) wire [15:0] mon_words = words;
    (* dont_touch = "true" *) wire [15:0] mon_runs = runs;
    (* dont_touch = "true" *) wire [15:0] mon_unlocks = unlocks;

`ifdef CARCH_NO_VIO
    assign vio_ctrl = INIT_CTRL;
    assign vio_seed = INIT_SEED;
    assign vio_a = INIT_A;
    assign vio_b = INIT_B;
    assign vio_rst = 1'b0;
`else
    vio_cfg u_vio (
        .clk(clk),
        .probe_in0(mon_result), .probe_in1(mon_words),
        .probe_in2(mon_runs), .probe_in3(mon_unlocks),
        .probe_out0(vio_ctrl), .probe_out1(vio_seed),
        .probe_out2(vio_a), .probe_out3(vio_b), .probe_out4(vio_rst)
    );
`endif

    // ---------------------------------------------------------------- reset
    (* ASYNC_REG = "TRUE" *) reg [1:0] locked_s = 2'b00;
    (* ASYNC_REG = "TRUE" *) reg [1:0] btn_s = 2'b00;
    reg [4:0] por = 5'd0;
    reg rst = 1'b1;
    reg rst_d = 1'b1, locked_d = 1'b0;

    always @(posedge clk) begin
        locked_s <= {locked_s[0], locked};
        btn_s <= {btn_s[0], btn0};
        if (!locked_s[1] || btn_s[1] || vio_rst)
            por <= 5'd0;
        else if (!por[4])
            por <= por + 5'd1;
        rst <= !por[4];
        // Monitors (never reset): firmware starts and MMCM lock losses.
        rst_d <= rst;
        locked_d <= locked_s[1];
        if (rst_d && !rst)
            runs <= runs + 16'd1;
        if (locked_d && !locked_s[1])
            unlocks <= unlocks + 16'd1;
    end

    // ---------------------------------------------------------------- SoC
    wire trap, result_valid, bus_error;

    soc_top #(.FIRMWARE(`FPGA_FIRMWARE), .CFG_WORDS(10), .ENABLE_ACCEL(ENABLE_ACCEL)) u_soc (
        .clk(clk), .rst(rst), .cfg_in({vio_b, vio_a, vio_seed, vio_ctrl}), .trap(trap),
        .result(result), .result_valid(result_valid), .bus_error(bus_error)
    );

    always @(posedge clk)
        if (rst)
            words <= 16'd0;
        else if (result_valid)
            words <= words + 16'd1;

    // ---------------------------------------------------------------- ILA taps
    // Registered copies of the result port, kept by mark_debug so build.tcl
    // can hook the ILA to them (read back over JTAG by hw.tcl).
    (* mark_debug = "true" *) reg [31:0] dbg_result = 32'd0;
    (* mark_debug = "true" *) reg dbg_valid = 1'b0;
    always @(posedge clk) begin
        dbg_result <= result;
        dbg_valid <= result_valid;
    end

    // ---------------------------------------------------------------- outputs
    wire overflow;

    uart_result_bridge #(.CLKS_PER_BIT(CLK_HZ / BAUD)) u_bridge (
        .clk(clk), .rst(rst), .valid(result_valid), .word(result),
        .tx(uart_tx), .overflow(overflow)
    );

    reg [25:0] beat = 26'd0;
    always @(posedge clk)
        beat <= beat + 26'd1;

    assign led[0] = beat[25];
    assign led[1] = (result == 32'd1);
    assign led[2] = (result[31:28] == 4'hF) || trap || bus_error;
    assign led[3] = overflow;
endmodule
